<script lang="ts">
 import {agentSession} from '$lib/agent/session.svelte'
 import {nestedComposition,nestedHistory,editNestedVideoEffects,reactivateNestedSourceEffect,editNestedConcatClipKeys,editNestedConcatPreparation} from '$lib/state/nestedComposition.svelte'
 import CropEditor from './ConcatCropEditor.svelte'
 import ClipAnimation from './ConcatClipAnimationEditor.svelte'
 let {disabled=false}:{disabled?:boolean}=$props()
 let compositionId=$derived(nestedComposition.activeCompositionId ?? nestedComposition.document?.root ?? '')
 let canvas=$derived(nestedComposition.document?.compositions[compositionId]?.content.canvas)
 let tracks=$derived(nestedComposition.document?.compositions[compositionId]?.content.tracks ?? [])
 const names:Record<string,string>={concat_bloom_pulse:"Concat Bloom Pulse",concat_glow:"Concat Glow",concat_film_grain:"Concat Film Grain",concat_halftone:"Concat Halftone",concat_motion_blur:"Concat Motion Blur",concat_zoom_blur:"Concat Zoom Blur",concat_fisheye:"Concat Fisheye",concat_chromatic_aberration:"Concat Chromatic Aberration",concat_gaussian_blur:"Concat Gaussian Blur",concat_posterize:"Concat Posterize",concat_luma_key:"Concat Luma Key",concat_pixelate:"Concat Pixelate",concat_chroma_key:"Concat Chroma Key",concat_golden_hour:"Concat Golden Hour",concat_daydream:"Concat Daydream",concat_cloudless_sky:"Concat Cloudless Sky",concat_lagoon:"Concat Lagoon",concat_polaroid:"Concat Polaroid",concat_vintage:"Concat Vintage",concat_fair:"Concat Fair",concat_peach:"Concat Peach",concat_rain:"Concat Rain",concat_umber:"Concat Umber",concat_soft_light:"Concat Soft Light",concat_moody:"Concat Moody",concat_fresh:"Concat Fresh",concat_vivid:"Concat Vivid",concat_bronze:"Concat Bronze",concat_cool_blue:"Concat Cool Blue",concat_ivory:"Concat Ivory",concat_milk:"Concat Milk",concat_matcha:"Concat Matcha",concat_sage:"Concat Sage",concat_clean:"Concat Clean",concat_autumn:"Concat Autumn",concat_neon:"Concat Neon",concat_pink_fuzz:"Concat Pink Fuzz",concat_night:"Concat Night",concat_spooky:"Concat Spooky",concat_cool:"Concat Cool",concat_warm:"Concat Warm",concat_teal_orange:"Concat Teal & Orange",concat_noir:"Concat Noir",concat_dreamy:"Concat Dreamy",concat_high_contrast_mono:"Concat High-Contrast Mono",concat_landscape_pop:"Concat Vivid Landscape",concat_natural:"Concat Natural",concat_retro_70s:"Concat Retro 70s",concat_silver:"Concat Silver",concat_tropical:"Concat Tropical",concat_vaporwave:"Concat Vaporwave",concat_winter_cool:"Concat Winter Cool",concat_classic_chrome:"Concat Classic Chrome",concat_cyberpunk:"Concat Cyberpunk",concat_delicious:"Concat Delicious",concat_rosy:"Concat Rosy",concat_sci_fi:"Concat Sci-Fi",concat_film:"Concat Film",concat_digicam:"Concat Digicam",concat_mono:"Concat Mono",concat_midnight:"Concat Midnight",concat_marquee:"Concat Marquee",concat_retro_cartoon:"Concat Retro Cartoon",concat_super8:"Concat Super 8",concat_bleach_bypass:"Concat Bleach Bypass",concat_contrast_pop:"Concat Contrast Pop",concat_sharpen:"Concat Sharpen",concat_vignette:"Concat Vignette",concat_adjust:"Concat Adjust",concat_saturation:"Concat Saturation",concat_curves:"Concat Curves",concat_color_wheels:"Concat Color Wheels",concat_white_balance:"Concat White Balance",concat_vibrance:"Concat Vibrance",concat_exposure:"Concat Exposure",concat_contrast:"Concat Contrast",graphic_text:'Форматированный текст',graphic_shape:'Графическая фигура',track_matte:'Track Matte Key',lightning:'Lightning',write_on:'Write-on',timecode:'Timecode',clip_name:'Clip Name',metadata_burnin:'Metadata Burn-in',simple_text:'Simple Text',vr_plane_to_sphere:'VR Plane to Sphere',vr_glow:'VR Glow',vr_fractal_noise:'VR Fractal Noise',vr_digital_glitch:'VR Digital Glitch',vr_color_gradients:'VR Color Gradients',vr_chromatic_aberrations:'VR Chromatic Aberrations',vr_denoise:'VR De-Noise',vr_blur:'VR Blur',vr_sharpen:'VR Sharpen',spherical_video:'360° видео',vr_projection:'VR Projection',vr_rotate_sphere:'VR Rotate Sphere',light_leaks:'Light Leaks',warp_stabilizer:'Warp Stabilizer',auto_reframe:'Auto Reframe',echo:'Echo',posterize_time:'Posterize Time',volumetric_rays:'Volumetric Rays',glint:'Glint',wonder_glow:'Wonder Glow',echo_glow:'Echo Glow',edge_glow:'Edge Glow',rgb_split:'RGB Split',logo_cutout:'Logo Cutout',lighting_effects:'Lighting Effects',compound_blur:'Compound Blur',bokeh_blur:'Bokeh Blur',focus_blur:'Focus Blur',crop:'Crop',vignette:'Vignette',transform:'Transform',asc_cdl:'ASC CDL',brightness_contrast:'Brightness & Contrast',unsharp_mask:'Unsharp Mask',edge_feather:'Edge Feather',sharpen:'Sharpen',reduce_interlace_flicker:'Reduce Interlace Flicker',channel_blur:'Channel Blur',turbulent_displace:'Turbulent Displace',auto_align:'Auto Align',clone:'Clone',rounded_crop:'Rounded Crop',spacer:'Spacer',camera_shake:'Camera Shake',wiggle:'Wiggle',move:'Move',spin:'Spin',grow:'Grow',shrink:'Shrink',rotate_3d:'3D Rotate',corner_pin:'Corner Pin',offset:'Offset',mirror:'Mirror',spherize:'Spherize',magnify:'Magnify',linear_wipe:'Linear Wipe',gradient_wipe:'Gradient Wipe',block_dissolve:'Block Dissolve',alpha_glow:'Alpha Glow',long_shadow:'Long Shadow',brush_strokes:'Brush Strokes',roughen_edges:'Roughen Edges',stroke:'Stroke',color_emboss:'Color Emboss',gradient:'Gradient',paint_bucket:'Paint Bucket',ellipse:'Ellipse',cell_pattern:'Cell Pattern',checkerboard:'Checkerboard',lens_flare:'Lens Flare',grid:'Grid',circle:'Circle',ramp:'Ramp',four_color_gradient:'4-Color Gradient',bevel_alpha:'Bevel Alpha',drop_shadow:'Drop Shadow',basic_3d:'Basic 3D',lens_distortion:'Lens Distortion',wave_warp:'Wave Warp',twirl:'Twirl',twirl_legacy:'Twirl Legacy',noise:'Noise',noise_legacy:'Noise Legacy',strobe:'Strobe Light',replicate:'Replicate',emboss:'Emboss',find_edges:'Find Edges',mosaic:'Mosaic',mosaic_legacy:'Mosaic Legacy',median:'Median',camera_blur:'Camera Blur',directional_blur:'Directional Blur',directional_blur_legacy:'Directional Blur Legacy',gaussian_blur:'Gaussian Blur',gaussian_blur_legacy:'Gaussian Blur Legacy',ultra_key:'Ultra Key',color_key:'Color Key',luma_key:'Luma Key',alpha_adjust:'Alpha Adjust',channel_mix:'Channel Mix',color_replace:'Color Replace',color_pass:'Color Pass',change_to_color:'Change to Color',leave_color:'Leave Color',color_balance:'Color Balance',color_tint:'Tint',horizontal_flip:'Horizontal Flip',vertical_flip:'Vertical Flip',black_white:'Black & White',color_extract:'Extract',color_levels:'Levels',color_invert:'Invert',posterize:'Posterize',gamma_correction:'Gamma Correction',proc_amp:'ProcAmp',cineon_converter:'Cineon Converter',video_limiter:'Video Limiter',tone_curves:'RGB-кривые',creative_grade:'Цветовые колёса',creative_adjust:'Творческая коррекция',basic_grade:'Базовая коррекция',color_lut:'LUT',color_sharpen:'Резкость',color_vignette:'Виньетка',lumetri:'Lumetri',hsl_secondary:'HSL Secondary',chroma_matte:'Chroma Matte',mask:'Маска',linear_mask:'Линейная маска'}
 function move(track:string,clip:string,index:number,delta:number) {
  void editNestedVideoEffects(compositionId,track,clip,effects=>{
   const next=index+delta
   if(next<0||next>=effects.length)return effects
   const result=[...effects];[result[index],result[next]]=[result[next]!,result[index]!]
   return result
  })
 }
</script>
<section aria-label="Порядок эффектов">
 {#if nestedHistory.error}<p role="alert">{nestedHistory.error}</p>{/if}
 {#each tracks as track (track.id)}
  {#if track.kind==='video'||track.kind==='image'||track.kind==='text'||track.kind==='graphic'}
   {#each track.clips as clip (clip.id)}
    {#if (track.kind!=='text'||('concatTitle' in clip&&clip.concatTitle))&&(track.kind!=='graphic'||('concatShape' in clip&&clip.concatShape)||('concatTreatment' in clip&&clip.concatTreatment))}
    {#if clip.effects?.length}
     <details><summary>{track.name} · {clip.id} · порядок эффектов</summary>
      {#each clip.effects as effect,index (index)}
       <div class="row">
        <span>{index+1}. {effect.kind==='concat_bypass'?`Отключён: ${effect.link.id}`:effect.kind==='native_bypass'?`Отключён: ${names[effect.effect.kind] ?? effect.effect.kind}`:names[effect.kind] ?? effect.kind}</span>
        <button class="btn ghost sm" aria-label={`${clip.id} effect ${index} enable`} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onclick={()=>{const selected=compositionId;void reactivateNestedSourceEffect(selected,track.id,clip.id,index,()=>{if(compositionId!==selected)throw new Error('Выбранная композиция изменилась')})}}>{effect.kind==='concat_bypass'||effect.kind==='native_bypass'?'Включить':'Отключить'}</button>
        <button class="btn ghost sm" aria-label={`${clip.id} effect ${index} up`} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)||index===0} onclick={()=>move(track.id,clip.id,index,-1)}>Выше</button>
        <button class="btn ghost sm" aria-label={`${clip.id} effect ${index} down`} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)||index===clip.effects!.length-1} onclick={()=>move(track.id,clip.id,index,1)}>Ниже</button>
        <button class="btn ghost sm" aria-label={`${clip.id} effect ${index} remove`} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onclick={()=>void editNestedVideoEffects(compositionId,track.id,clip.id,effects=>effects.filter((_,i)=>i!==index))}>Удалить</button>
       </div>
      {/each}
     </details>
    {/if}
    {#if clip.transform?.concatPreparation||(((track.kind==='text'&&'concatTitle' in clip&&clip.concatTitle)||(track.kind==='graphic'&&'concatShape' in clip&&clip.concatShape))&&canvas)}<details><summary>{track.name} · {clip.id} · обрезка и отражения</summary><CropEditor preparation={clip.transform.concatPreparation??{crop:[0,0,0,0],canvas:[canvas!.width,canvas!.height]}} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onchange={edit=>{const selected=compositionId;void editNestedConcatPreparation(selected,track.id,clip.id,edit,()=>{if(compositionId!==selected)throw new Error('Выбранная композиция изменилась')})}}/></details>{/if}
    {#if ((track.kind==='text'&&'concatTitle' in clip&&clip.concatTitle)||(track.kind==='graphic'&&'concatShape' in clip&&clip.concatShape))&&!clip.transform.concatAnimation}
     <button class="btn ghost sm" aria-label={`${clip.id} initialize Concat animation`} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onclick={()=>{const selected=compositionId;void editNestedConcatClipKeys(selected,track.id,clip.id,'opacity',[],()=>{if(compositionId!==selected)throw new Error('Выбранная композиция изменилась')})}}>Включить анимацию Concat</button>
    {/if}
    {#if clip.transform?.concatAnimation}<div data-concat-motion={clip.id}><ClipAnimation animation={clip.transform.concatAnimation} disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onchange={(property,keys)=>{const selected=compositionId;void editNestedConcatClipKeys(selected,track.id,clip.id,property,keys,()=>{if(compositionId!==selected)throw new Error('Выбранная композиция изменилась')})}}/></div>{/if}
    {/if}
   {/each}
  {/if}
 {/each}
</section>
<style>.row{display:flex;align-items:center;gap:0.5rem;flex-wrap:wrap}.row span{min-width:12rem}</style>
